import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.4yUrvjMt.js";const h=JSON.parse('{"title":"ADR-003: Zod for Schema Validation","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/decisions/ADR-003-zod-schema-validation.md","filePath":"architecture/decisions/ADR-003-zod-schema-validation.md"}'),r={name:"architecture/decisions/ADR-003-zod-schema-validation.md"};function n(s,e,d,c,l,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-003-zod-for-schema-validation" tabindex="-1">ADR-003: Zod for Schema Validation <a class="header-anchor" href="#adr-003-zod-for-schema-validation" aria-label="Permalink to &quot;ADR-003: Zod for Schema Validation&quot;">​</a></h1><p><strong>Status:</strong> Accepted<br><strong>Date:</strong> 2024-01-01</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>TypeScript types are erased at runtime. Step inputs and outputs can be any shape at runtime, even if TypeScript thinks they&#39;re typed. We need runtime validation at every step boundary.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Every <code>Step</code> carries <code>inputSchema</code> and <code>outputSchema</code> as Zod schemas. <code>BaseStep.execute</code> validates input before calling <code>run</code> and validates output before returning. Validation failures throw <code>ValidationError</code> with full Zod issue details.</p><p>Zod was chosen over alternatives because:</p><ul><li>It is the only mandatory dependency of <code>@pravaha/core</code> (acceptable tradeoff)</li><li>It produces TypeScript types from schemas (<code>z.infer&lt;typeof Schema&gt;</code>)</li><li>Error messages are actionable and machine-readable</li><li>It has no runtime dependencies of its own</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive:</strong></p><ul><li>Type safety enforced at runtime, not just compile time</li><li>Validation errors carry structured issue details for debugging</li><li>Schema doubles as documentation for step contracts</li></ul><p><strong>Negative:</strong></p><ul><li>Zod is a mandatory peer dependency — cannot be avoided</li><li>Validation overhead on every step (acceptable for I/O boundaries)</li><li>Large schemas can be verbose</li></ul>',13)])])}const m=a(r,[["render",n]]);export{h as __pageData,m as default};
